void CommandList::destroyAllMessages()
{
	GameMessage *msg, *nextMsg;
	for (msg = m_firstMessage; msg; msg = nextMsg)
	{
		nextMsg = msg->m_next;
		::delete msg;
	}
	m_firstMessage = 0;
	m_lastMessage = 0;
}

// FUNCTION: BFME2 0x0030F880 size=34 name=?appendMessageList@CommandList@@QAEXPAVGameMessage@@@Z evidence=N:ledger
void CommandList::appendMessageList(GameMessage *list)
{
	GameMessage *msg, *next;

	for (msg = list; msg; msg = next) {
		next = msg->next();
		appendMessage(msg);
	}
}

// FUNCTION: BFME2 0x0030F8A2 size=65 name=?buildRegion@@YAXPBUICoord2D@@0PAUIRegion2D@@@Z evidence=N:ledger
void buildRegion( const ICoord2D *anchor, const ICoord2D *dest, IRegion2D *region )
{
	// The region spans the two drag corners whichever way they were dragged.
	if (anchor->x < dest->x)
	{
		region->lo.x = anchor->x;
		region->hi.x = dest->x;
	}
	else
	{
		region->lo.x = dest->x;
		region->hi.x = anchor->x;
	}

	if (anchor->y < dest->y)
	{
		region->lo.y = anchor->y;
		region->hi.y = dest->y;
	}
	else
	{
		region->lo.y = dest->y;
		region->hi.y = anchor->y;
	}
}

