// FUNCTION: BFME2 0x00310FA1 size=84 name=??1MessageStream@@UAE@XZ evidence=N:ledger
MessageStream::~MessageStream()
{
	TranslatorData *doomed, *following;
	for (doomed = m_firstTranslator; doomed; doomed = following)
	{
		following = doomed->m_next;
		delete doomed;
	}
}

// FUNCTION: BFME2 0x00310FF5 size=101 name=?propagateMessages@MessageStream@@QAEXXZ evidence=N:ledger
void MessageStream::propagateMessages(void)
{
	TranslatorData *translator;
	GameMessage *message;
	GameMessage *next;

	for (translator = m_firstTranslator; translator; translator = translator->m_next)
	{
		for (message = m_firstMessage; message; message = next)
		{
			if (translator->m_translator)
			{
				GameMessageDisposition disposition =
					translator->m_translator->translateGameMessage(message);
				next = message->next();
				if (disposition == DESTROY_MESSAGE)
					::delete message;
			}
			else
			{
				next = message->next();
			}
		}
	}

	TheCommandList->appendMessageList(m_firstMessage);
	m_firstMessage = 0;
	m_lastMessage = 0;
}

